INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, payload) VALUES ('crd.root-transformer', 'card', 'Transformer 架构：从张量到概率', 'root-transformer', NULL, '{"id": "crd.root-transformer", "type": "card", "title": "Transformer 架构：从张量到概率", "outlinePath": "root-transformer", "summary": "这份讲义只讲一件事：一个前馈网络块里，张量是怎么一层层走过去的，层与层之间靠什么条件才能接上。", "body": "这份讲义只讲一件事：**一个前馈网络块里，张量是怎么一层层走过去的，层与层之间靠什么条件才能接上。**\n\n选择这个主题做图谱的第一份语料，是因为它的每一条依赖都能给出具体判据（形状、值域、统计量、梯度、语义），也就能把「以为懂了、其实判断错了」的地方精确地定位出来。", "chain": [], "crossLinks": [{"target": "crd.s6", "targetKind": "card", "label": "6 小结", "weight": 1.0, "reason": "共享实体：张量形状"}, {"target": "crd.s1-2-relu", "targetKind": "card", "label": "1.2 ReLU", "weight": 0.71, "reason": "共享实体：张量形状"}, {"target": "crd.s2", "targetKind": "card", "label": "2 层与层之间的五种依赖", "weight": 0.71, "reason": "共享实体：张量形状"}, {"target": "crd.s2-1", "targetKind": "card", "label": "2.1 形状依赖", "weight": 0.5, "reason": "共享实体：张量形状"}, {"target": "crd.s2-4", "targetKind": "card", "label": "2.4 梯度路径依赖", "weight": 0.5, "reason": "共享实体：张量形状"}], "claimIds": []}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, payload) VALUES ('crd.s1', 'card', '1 前馈网络：从张量到概率', 's1', NULL, '{"id": "crd.s1", "type": "card", "title": "1 前馈网络：从张量到概率", "outlinePath": "s1", "summary": "看起来只有五个组件，但每一步都能接不上的地方各不相同：形状对不对、取值范围合不合适、归一化沿哪一维、梯度有没有被截断、含义是不是那个意思。", "body": "一个最小编码块可以写成下面这条链：\n\n```text\nLinear → ReLU → Linear → Softmax → CrossEntropy\n```\n\n看起来只有五个组件，但每一步都能接不上的地方各不相同：形状对不对、取值范围合不合适、归一化沿哪一维、梯度有没有被截断、含义是不是那个意思。", "chain": ["ent.method.linear.cb1f", "ent.method.relu.2233", "ent.method.linear.cb1f", "ent.method.softmax.2e55", "ent.metric.crossentropy.d6a5"], "crossLinks": [{"target": "crd.s2-1", "targetKind": "card", "label": "2.1 形状依赖", "weight": 0.67, "reason": "共享实体：张量形状、Linear、ReLU"}, {"target": "crd.s1-2-relu", "targetKind": "card", "label": "1.2 ReLU", "weight": 0.66, "reason": "共享实体：张量形状、ReLU"}, {"target": "crd.s1-4", "targetKind": "card", "label": "1.4 交叉熵损失", "weight": 0.63, "reason": "共享实体：Linear、Softmax、CrossEntropy"}, {"target": "crd.s2-5", "targetKind": "card", "label": "2.5 语义依赖", "weight": 0.6, "reason": "共享实体：张量形状、ReLU、Softmax"}, {"target": "crd.s5-1", "targetKind": "card", "label": "5.1 判断题表", "weight": 0.47, "reason": "共享实体：ReLU、Softmax、CrossEntropy"}], "claimIds": []}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, payload) VALUES ('crd.s1-1-linear', 'card', '1.1 Linear 层', 's1-1-linear', NULL, '{"id": "crd.s1-1-linear", "type": "card", "title": "1.1 Linear 层", "outlinePath": "s1-1-linear", "summary": "Linear 层做的是仿射变换：y = x @ W.T + b。", "body": "**Linear** 层做的是仿射变换：`y = x @ W.T + b`。输入 `x` 的形状通常是 `(N, in_features)`，权重 `W` 的形状是 `(out_features, in_features)`，输出是 `(N, out_features)`。它只动最后一维，前面的维度（批次、序列长度）原样保留。\n\n这也是为什么 **batch** 大小不影响参数量：参数只有 `W` 和 `b` 两块，与 `N` 无关。", "chain": [], "crossLinks": [{"target": "crd.s1", "targetKind": "card", "label": "1 前馈网络：从张量到概率", "weight": 0.35, "reason": "共享实体：张量形状、Linear"}, {"target": "crd.s2-1", "targetKind": "card", "label": "2.1 形状依赖", "weight": 0.35, "reason": "共享实体：张量形状、Linear"}, {"target": "crd.s6", "targetKind": "card", "label": "6 小结", "weight": 0.35, "reason": "共享实体：张量形状"}, {"target": "crd.root-transformer", "targetKind": "card", "label": "Transformer 架构：从张量到概率", "weight": 0.35, "reason": "共享实体：张量形状"}, {"target": "crd.s1-2-relu", "targetKind": "card", "label": "1.2 ReLU", "weight": 0.28, "reason": "共享实体：张量形状"}], "claimIds": ["clm.arch.ffn.linear-in-dim.4a3e", "clm.arch.ffn.linear-param-batch.2fe7"]}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, payload) VALUES ('crd.s1-2-relu', 'card', '1.2 ReLU', 's1-2-relu', NULL, '{"id": "crd.s1-2-relu", "type": "card", "title": "1.2 ReLU", "outlinePath": "s1-2-relu", "summary": "ReLU 是逐元素激活：max(0, x)。", "body": "**ReLU** 是逐元素激活：`max(0, x)`。它不改变张量形状，只把负半轴压成 0。正因为是逐元素操作，它可以接在任何形状之后，不需要额外的形状对齐。\n\n代价在梯度上：输入为负时导数为 0，该神经元的参数在这一步不会更新；如果一层神经元的输入长期全负，就会整片「死掉」。", "chain": [], "crossLinks": [{"target": "crd.s2-1", "targetKind": "card", "label": "2.1 形状依赖", "weight": 0.71, "reason": "共享实体：张量形状、ReLU"}, {"target": "crd.s2-4", "targetKind": "card", "label": "2.4 梯度路径依赖", "weight": 0.71, "reason": "共享实体：张量形状、ReLU"}, {"target": "crd.s6", "targetKind": "card", "label": "6 小结", "weight": 0.71, "reason": "共享实体：张量形状"}, {"target": "crd.root-transformer", "targetKind": "card", "label": "Transformer 架构：从张量到概率", "weight": 0.71, "reason": "共享实体：张量形状"}, {"target": "crd.s1", "targetKind": "card", "label": "1 前馈网络：从张量到概率", "weight": 0.66, "reason": "共享实体：张量形状、ReLU"}], "claimIds": ["clm.arch.ffn.relu-shape.6092", "clm.arch.ffn.relu-zero-grad.8ab0", "clm.arch.ffn.relu-differentiable.a702"]}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, payload) VALUES ('crd.s1-3-softmax', 'card', '1.3 Softmax', 's1-3-softmax', NULL, '{"id": "crd.s1-3-softmax", "type": "card", "title": "1.3 Softmax", "outlinePath": "s1-3-softmax", "summary": "Softmax 把一组实数压成概率分布：softmax(z)_i = exp(z_i) / sum_j exp(z_j)。", "body": "**Softmax** 把一组实数压成概率分布：`softmax(z)_i = exp(z_i) / sum_j exp(z_j)`。它沿**类别维**归约，输出与输入同形，且每一行求和为 1。\n\n它有一个常被忽略的性质：**整体平移不变**。给所有 logits 加同一个常数，输出完全不变 —— 这也是数值稳定实现「先减最大值」的依据。", "chain": [], "crossLinks": [{"target": "crd.s1-4", "targetKind": "card", "label": "1.4 交叉熵损失", "weight": 0.48, "reason": "共享实体：logits、Softmax"}, {"target": "crd.s2-5", "targetKind": "card", "label": "2.5 语义依赖", "weight": 0.45, "reason": "共享实体：logits、Softmax"}, {"target": "crd.s5-1", "targetKind": "card", "label": "5.1 判断题表", "weight": 0.35, "reason": "共享实体：logits、Softmax"}, {"target": "crd.s1", "targetKind": "card", "label": "1 前馈网络：从张量到概率", "weight": 0.25, "reason": "共享实体：Softmax"}, {"target": "crd.s4-2", "targetKind": "card", "label": "4.2 掩码", "weight": 0.25, "reason": "共享实体：Softmax"}], "claimIds": ["clm.arch.ffn.softmax-sum.a505", "clm.arch.ffn.softmax-dim.4af1", "clm.arch.ffn.softmax-shift.6358"]}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, payload) VALUES ('crd.s1-4', 'card', '1.4 交叉熵损失', 's1-4', NULL, '{"id": "crd.s1-4", "type": "card", "title": "1.4 交叉熵损失", "outlinePath": "s1-4", "summary": "CrossEntropy 接收的是未归一化的 logits，内部已经做了 log-softmax。", "body": "**CrossEntropy** 接收的是未归一化的 **logits**，内部已经做了 log-softmax。所以正确的用法是「最后一层 Linear 直接出 logits，送进 CrossEntropy」，而不是先 Softmax 再送。\n\n先 Softmax 再送 CrossEntropy，数学上不等于直接送 logits：链式求导后梯度被额外乘了一个 `p(1-p)` 因子，训练会明显变慢，甚至学不动。", "chain": [], "crossLinks": [{"target": "crd.s1", "targetKind": "card", "label": "1 前馈网络：从张量到概率", "weight": 0.63, "reason": "共享实体：Linear、Softmax、CrossEntropy"}, {"target": "crd.s1-3-softmax", "targetKind": "card", "label": "1.3 Softmax", "weight": 0.48, "reason": "共享实体：logits、Softmax"}, {"target": "crd.s5-1", "targetKind": "card", "label": "5.1 判断题表", "weight": 0.47, "reason": "共享实体：logits、Softmax、CrossEntropy"}, {"target": "crd.s2-5", "targetKind": "card", "label": "2.5 语义依赖", "weight": 0.4, "reason": "共享实体：logits、Softmax"}, {"target": "crd.s2-1", "targetKind": "card", "label": "2.1 形状依赖", "weight": 0.22, "reason": "共享实体：Linear"}], "claimIds": ["clm.arch.ffn.ce-logits.5a91", "clm.arch.ffn.ce-double-softmax.eed8"]}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, payload) VALUES ('crd.s2', 'card', '2 层与层之间的五种依赖', 's2', NULL, '{"id": "crd.s2", "type": "card", "title": "2 层与层之间的五种依赖", "outlinePath": "s2", "summary": "形状对得上只是最低门槛。", "body": "形状对得上只是最低门槛。真正决定「能不能接」的，是下面五类依赖中的至少一类。判断一条连接是否成立，本质上是在问：**这五条里，哪一条被违反了。**", "chain": [], "crossLinks": [{"target": "crd.s6", "targetKind": "card", "label": "6 小结", "weight": 0.71, "reason": "共享实体：张量形状"}, {"target": "crd.root-transformer", "targetKind": "card", "label": "Transformer 架构：从张量到概率", "weight": 0.71, "reason": "共享实体：张量形状"}, {"target": "crd.s1-2-relu", "targetKind": "card", "label": "1.2 ReLU", "weight": 0.5, "reason": "共享实体：张量形状"}, {"target": "crd.s2-1", "targetKind": "card", "label": "2.1 形状依赖", "weight": 0.38, "reason": "共享实体：张量形状"}, {"target": "crd.s2-4", "targetKind": "card", "label": "2.4 梯度路径依赖", "weight": 0.38, "reason": "共享实体：张量形状"}], "claimIds": []}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, payload) VALUES ('crd.s2-1', 'card', '2.1 形状依赖', 's2-1', NULL, '{"id": "crd.s2-1", "type": "card", "title": "2.1 形状依赖", "outlinePath": "s2-1", "summary": "张量形状是最容易检查的一层：上游输出的最后一维，必须等于下游期望的输入维。", "body": "**张量形状**是最容易检查的一层：上游输出的最后一维，必须等于下游期望的输入维。**Linear** 之后接任意逐元素激活（如 **ReLU**、**GELU**）都不需要额外对齐，因为逐元素操作保持形状。", "chain": [], "crossLinks": [{"target": "crd.s1-2-relu", "targetKind": "card", "label": "1.2 ReLU", "weight": 0.71, "reason": "共享实体：张量形状、ReLU"}, {"target": "crd.s1", "targetKind": "card", "label": "1 前馈网络：从张量到概率", "weight": 0.67, "reason": "共享实体：张量形状、Linear、ReLU"}, {"target": "crd.s2-4", "targetKind": "card", "label": "2.4 梯度路径依赖", "weight": 0.53, "reason": "共享实体：张量形状、ReLU"}, {"target": "crd.s6", "targetKind": "card", "label": "6 小结", "weight": 0.5, "reason": "共享实体：张量形状"}, {"target": "crd.root-transformer", "targetKind": "card", "label": "Transformer 架构：从张量到概率", "weight": 0.5, "reason": "共享实体：张量形状"}], "claimIds": ["clm.arch.dep.shape.85dd"]}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, payload) VALUES ('crd.s2-2', 'card', '2.2 值域依赖', 's2-2', NULL, '{"id": "crd.s2-2", "type": "card", "title": "2.2 值域依赖", "outlinePath": "s2-2", "summary": "值域依赖问的是输出取值范围是否符合下游假设。", "body": "**值域依赖**问的是输出取值范围是否符合下游假设。**Sigmoid** 输出恒为正且落在 (0,1)，二分类可以直接当概率；但多分类若直接用它，各类概率之和不为 1，还需要额外归一化。", "chain": [], "crossLinks": [], "claimIds": ["clm.arch.dep.range-sigmoid.0888"]}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, payload) VALUES ('crd.s2-3', 'card', '2.3 统计量依赖', 's2-3', NULL, '{"id": "crd.s2-3", "type": "card", "title": "2.3 统计量依赖", "outlinePath": "s2-3", "summary": "LayerNorm 与 BatchNorm 的差别不在公式，而在沿哪一维算统计量：LayerNorm 在特征维上算，与 batch 无关；Bat…", "body": "**LayerNorm** 与 **BatchNorm** 的差别不在公式，而在**沿哪一维算统计量**：LayerNorm 在特征维上算，与 batch 无关；BatchNorm 在 batch 维上算，batch 太小统计量就不可靠。", "chain": [], "crossLinks": [{"target": "crd.s3-1-layernorm-batchnorm", "targetKind": "card", "label": "3.1 LayerNorm 与 BatchNorm", "weight": 0.87, "reason": "共享实体：batch、BatchNorm、LayerNorm"}, {"target": "crd.s3-3-pre-ln-post-ln", "targetKind": "card", "label": "3.3 Pre-LN 与 Post-LN", "weight": 0.25, "reason": "共享实体：LayerNorm"}, {"target": "crd.s1-1-linear", "targetKind": "card", "label": "1.1 Linear 层", "weight": 0.18, "reason": "共享实体：batch"}, {"target": "crd.s5-1", "targetKind": "card", "label": "5.1 判断题表", "weight": 0.18, "reason": "共享实体：BatchNorm"}], "claimIds": ["clm.arch.dep.stats-dim.e92b", "clm.arch.dep.bn-small-batch.b33d"]}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, payload) VALUES ('crd.s2-4', 'card', '2.4 梯度路径依赖', 's2-4', NULL, '{"id": "crd.s2-4", "type": "card", "title": "2.4 梯度路径依赖", "outlinePath": "s2-4", "summary": "梯度路径依赖问的是梯度能不能从下游回传到上游。", "body": "**梯度路径依赖**问的是梯度能不能从下游回传到上游。**残差连接**给梯度提供了一条恒等捷径，前提是主分支与捷径的形状一致；**ReLU** 的死区则会直接切断梯度通道。", "chain": [], "crossLinks": [{"target": "crd.s1-2-relu", "targetKind": "card", "label": "1.2 ReLU", "weight": 0.71, "reason": "共享实体：张量形状、ReLU"}, {"target": "crd.s2-1", "targetKind": "card", "label": "2.1 形状依赖", "weight": 0.53, "reason": "共享实体：张量形状、ReLU"}, {"target": "crd.s3-2", "targetKind": "card", "label": "3.2 残差连接", "weight": 0.5, "reason": "共享实体：残差连接"}, {"target": "crd.s6", "targetKind": "card", "label": "6 小结", "weight": 0.5, "reason": "共享实体：张量形状"}, {"target": "crd.root-transformer", "targetKind": "card", "label": "Transformer 架构：从张量到概率", "weight": 0.5, "reason": "共享实体：张量形状"}], "claimIds": ["clm.arch.dep.grad-residual.8054", "clm.arch.dep.grad-relu-dead.ebf3"]}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, payload) VALUES ('crd.s2-5', 'card', '2.5 语义依赖', 's2-5', NULL, '{"id": "crd.s2-5", "type": "card", "title": "2.5 语义依赖", "outlinePath": "s2-5", "summary": "语义依赖是最隐蔽的一层：形状对得上、值域也合适，但含义不对。", "body": "**语义依赖**是最隐蔽的一层：形状对得上、值域也合适，但含义不对。典型例子是「**ReLU** 之后直接接 **Softmax**」—— 形状完全相容，可 ReLU 的输出不是 logits，Softmax 会把「非负但未归一化」的数当成得分来归一化，训练时梯度分布被扭曲。", "chain": [], "crossLinks": [{"target": "crd.s1-2-relu", "targetKind": "card", "label": "1.2 ReLU", "weight": 0.63, "reason": "共享实体：张量形状、ReLU"}, {"target": "crd.s1", "targetKind": "card", "label": "1 前馈网络：从张量到概率", "weight": 0.6, "reason": "共享实体：张量形状、ReLU、Softmax"}, {"target": "crd.s2-1", "targetKind": "card", "label": "2.1 形状依赖", "weight": 0.48, "reason": "共享实体：张量形状、ReLU"}, {"target": "crd.s2-4", "targetKind": "card", "label": "2.4 梯度路径依赖", "weight": 0.48, "reason": "共享实体：张量形状、ReLU"}, {"target": "crd.s5-1", "targetKind": "card", "label": "5.1 判断题表", "weight": 0.47, "reason": "共享实体：logits、ReLU、Softmax"}], "claimIds": ["clm.arch.dep.semantic.7874", "clm.arch.dep.relu-then-softmax.d07e"]}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, payload) VALUES ('crd.s3-1-layernorm-batchnorm', 'card', '3.1 LayerNorm 与 BatchNorm', 's3-1-layernorm-batchnorm', NULL, '{"id": "crd.s3-1-layernorm-batchnorm", "type": "card", "title": "3.1 LayerNorm 与 BatchNorm", "outlinePath": "s3-1-layernorm-batchnorm", "summary": "两者的公式几乎一样，差别只在统计量的来源。", "body": "两者的公式几乎一样，差别只在统计量的来源。**LayerNorm** 在单样本内部沿特征维归一化，天然适配变长序列和小 batch；**BatchNorm** 依赖批内统计量，推理时改用训练期累积的滑动统计量。", "chain": [], "crossLinks": [{"target": "crd.s2-3", "targetKind": "card", "label": "2.3 统计量依赖", "weight": 0.87, "reason": "共享实体：batch、BatchNorm、LayerNorm"}, {"target": "crd.s3-3-pre-ln-post-ln", "targetKind": "card", "label": "3.3 Pre-LN 与 Post-LN", "weight": 0.32, "reason": "共享实体：LayerNorm"}, {"target": "crd.s1-1-linear", "targetKind": "card", "label": "1.1 Linear 层", "weight": 0.2, "reason": "共享实体：batch"}, {"target": "crd.s5-1", "targetKind": "card", "label": "5.1 判断题表", "weight": 0.2, "reason": "共享实体：BatchNorm"}], "claimIds": ["clm.arch.train.ln-dim.8cae", "clm.arch.train.bn-infer.7ae7"]}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, payload) VALUES ('crd.s3-2', 'card', '3.2 残差连接', 's3-2', NULL, '{"id": "crd.s3-2", "type": "card", "title": "3.2 残差连接", "outlinePath": "s3-2", "summary": "残差连接把 y = F(x) + x 写进结构里，一方面让梯度有恒等通路，另一方面让网络学「增量」而不是「全量」。", "body": "**残差连接**把 `y = F(x) + x` 写进结构里，一方面让梯度有恒等通路，另一方面让网络学「增量」而不是「全量」。", "chain": [], "crossLinks": [{"target": "crd.s3-3-pre-ln-post-ln", "targetKind": "card", "label": "3.3 Pre-LN 与 Post-LN", "weight": 0.53, "reason": "共享实体：残差连接"}, {"target": "crd.s2-4", "targetKind": "card", "label": "2.4 梯度路径依赖", "weight": 0.5, "reason": "共享实体：残差连接"}], "claimIds": ["clm.arch.train.residual-shape.b560"]}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, payload) VALUES ('crd.s3-3-pre-ln-post-ln', 'card', '3.3 Pre-LN 与 Post-LN', 's3-3-pre-ln-post-ln', NULL, '{"id": "crd.s3-3-pre-ln-post-ln", "type": "card", "title": "3.3 Pre-LN 与 Post-LN", "outlinePath": "s3-3-pre-ln-post-ln", "summary": "Pre-LN 把归一化放在子层之前，残差通路上没有任何归一化，梯度可以无损回传；Post-LN 把归一化放在残差相加之后，深层网络训练更依赖 w…", "body": "**Pre-LN** 把归一化放在子层之前，残差通路上没有任何归一化，梯度可以无损回传；**Post-LN** 把归一化放在残差相加之后，深层网络训练更依赖 warmup。", "chain": [], "crossLinks": [{"target": "crd.s3-2", "targetKind": "card", "label": "3.2 残差连接", "weight": 0.53, "reason": "共享实体：残差连接"}, {"target": "crd.s3-1-layernorm-batchnorm", "targetKind": "card", "label": "3.1 LayerNorm 与 BatchNorm", "weight": 0.32, "reason": "共享实体：LayerNorm"}, {"target": "crd.s2-3", "targetKind": "card", "label": "2.3 统计量依赖", "weight": 0.25, "reason": "共享实体：LayerNorm"}, {"target": "crd.s2-4", "targetKind": "card", "label": "2.4 梯度路径依赖", "weight": 0.25, "reason": "共享实体：残差连接"}], "claimIds": ["clm.arch.train.pre-ln.b81c", "clm.arch.train.post-ln-deep.d2c5"]}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, payload) VALUES ('crd.s4-1', 'card', '4.1 缩放点积注意力', 's4-1', NULL, '{"id": "crd.s4-1", "type": "card", "title": "4.1 缩放点积注意力", "outlinePath": "s4-1", "summary": "缩放点积注意力是 softmax(QK^T / sqrt(d_k)) V。", "body": "**缩放点积注意力**是 `softmax(QK^T / sqrt(d_k)) V`。除以 `sqrt(d_k)` 不是装饰：点积的方差随 `d_k` 线性增长，不缩放会让 Softmax 进入饱和区，梯度接近 0。", "chain": [], "crossLinks": [{"target": "crd.s4-2", "targetKind": "card", "label": "4.2 掩码", "weight": 0.25, "reason": "共享实体：Softmax"}, {"target": "crd.s1-3-softmax", "targetKind": "card", "label": "1.3 Softmax", "weight": 0.22, "reason": "共享实体：Softmax"}, {"target": "crd.s1", "targetKind": "card", "label": "1 前馈网络：从张量到概率", "weight": 0.2, "reason": "共享实体：Softmax"}, {"target": "crd.s1-4", "targetKind": "card", "label": "1.4 交叉熵损失", "weight": 0.2, "reason": "共享实体：Softmax"}, {"target": "crd.s2-5", "targetKind": "card", "label": "2.5 语义依赖", "weight": 0.2, "reason": "共享实体：Softmax"}], "claimIds": ["clm.arch.attn.scale.2883", "clm.arch.attn.no-scale.1418"]}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, payload) VALUES ('crd.s4-2', 'card', '4.2 掩码', 's4-2', NULL, '{"id": "crd.s4-2", "type": "card", "title": "4.2 掩码", "outlinePath": "s4-2", "summary": "因果掩码必须在 Softmax 之前把未来位置置为 -inf。", "body": "**因果掩码**必须在 Softmax **之前**把未来位置置为 `-inf`。先 Softmax 再乘 0 不等价：归一化时未来位置已经参与了分母，概率质量被摊薄，等于让模型偷看了答案。", "chain": [], "crossLinks": [{"target": "crd.s1-3-softmax", "targetKind": "card", "label": "1.3 Softmax", "weight": 0.25, "reason": "共享实体：Softmax"}, {"target": "crd.s4-1", "targetKind": "card", "label": "4.1 缩放点积注意力", "weight": 0.25, "reason": "共享实体：Softmax"}, {"target": "crd.s1", "targetKind": "card", "label": "1 前馈网络：从张量到概率", "weight": 0.22, "reason": "共享实体：Softmax"}, {"target": "crd.s1-4", "targetKind": "card", "label": "1.4 交叉熵损失", "weight": 0.22, "reason": "共享实体：Softmax"}, {"target": "crd.s2-5", "targetKind": "card", "label": "2.5 语义依赖", "weight": 0.22, "reason": "共享实体：Softmax"}], "claimIds": ["clm.arch.attn.mask-before-softmax.f3c1", "clm.arch.attn.mask-after.ca87"]}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, payload) VALUES ('crd.s4-3', 'card', '4.3 多头注意力', 's4-3', NULL, '{"id": "crd.s4-3", "type": "card", "title": "4.3 多头注意力", "outlinePath": "s4-3", "summary": "多头注意力把 d_model 切成 h 份并行做注意力，每个头在自己的子空间里学一种关系模式，最后拼接再做一次线性投影。", "body": "**多头注意力**把 `d_model` 切成 `h` 份并行做注意力，每个头在自己的子空间里学一种关系模式，最后拼接再做一次线性投影。各头之间是**子空间划分**关系，不是独立模型。", "chain": [], "crossLinks": [], "claimIds": ["clm.arch.attn.mha-concat.cffd", "clm.arch.attn.mha-heads-independent.b0da"]}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, payload) VALUES ('crd.s4-4', 'card', '4.4 位置编码', 's4-4', NULL, '{"id": "crd.s4-4", "type": "card", "title": "4.4 位置编码", "outlinePath": "s4-4", "summary": "自注意力对输入顺序是置换等变的：把 token 打乱，输出只是跟着打乱，模型本身感知不到「谁在前」。", "body": "自注意力对输入顺序是**置换等变**的：把 token 打乱，输出只是跟着打乱，模型本身感知不到「谁在前」。因此必须额外注入位置信息，这就是**位置编码**存在的原因。", "chain": [], "crossLinks": [], "claimIds": ["clm.arch.attn.pos-encoding-needed.3780"]}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, payload) VALUES ('crd.s5', 'card', '5 常见误区速查', 's5', NULL, '{"id": "crd.s5", "type": "card", "title": "5 常见误区速查", "outlinePath": "s5", "summary": "下面这张表是判断题形式的速查清单，用于快速自测。", "body": "下面这张表是判断题形式的速查清单，用于快速自测。第三条「边界」说明什么情况下结论会翻转 —— 这一列就是深度图谱里「条件」的来源。", "chain": [], "crossLinks": [], "claimIds": ["clm.arch.s5.boundary.92a4"]}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, payload) VALUES ('crd.s5-1', 'card', '5.1 判断题表', 's5-1', NULL, '{"id": "crd.s5-1", "type": "card", "title": "5.1 判断题表", "outlinePath": "s5-1", "summary": "ReLU 在整个实数域上处处可微；不成立；x=0 处左右导数不等", "body": "| 判断句 | 是否成立 | 边界 |\n|---|---|---|\n| ReLU 在整个实数域上处处可微 | 不成立 | x=0 处左右导数不等 |\n| Dropout 在推理阶段仍需随机置零 | 不成立 | 推理阶段关闭，训练阶段才随机置零 |\n| BatchNorm 在推理阶段使用训练期累积的滑动统计量 | 成立 | 必须显式切换到 eval 模式 |\n| 交叉熵对 logits 的梯度等于 softmax 输出减 one-hot | 成立 | 仅当损失内部做 log-softmax 时成立 |\n| Adam 优化器不需要设置学习率 | 不成立 | 仍需学习率，只是自适应调整每个参数的步长 |\n| Softmax 的输出可以直接当作模型置信度使用 | 不成立 | 未校准的概率分布会系统性偏高 |", "chain": [], "crossLinks": [{"target": "crd.s1", "targetKind": "card", "label": "1 前馈网络：从张量到概率", "weight": 0.47, "reason": "共享实体：ReLU、Softmax、CrossEntropy"}, {"target": "crd.s1-4", "targetKind": "card", "label": "1.4 交叉熵损失", "weight": 0.47, "reason": "共享实体：logits、Softmax、CrossEntropy"}, {"target": "crd.s2-5", "targetKind": "card", "label": "2.5 语义依赖", "weight": 0.47, "reason": "共享实体：logits、ReLU、Softmax"}, {"target": "crd.s1-3-softmax", "targetKind": "card", "label": "1.3 Softmax", "weight": 0.35, "reason": "共享实体：logits、Softmax"}, {"target": "crd.s1-2-relu", "targetKind": "card", "label": "1.2 ReLU", "weight": 0.25, "reason": "共享实体：ReLU"}], "claimIds": ["clm.arch.qa.q2.2899", "clm.arch.qa.q3.a531", "clm.arch.qa.q4.51c7", "clm.arch.qa.q5.6e65", "clm.arch.qa.q6.55d7"]}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, payload) VALUES ('crd.s6', 'card', '6 小结', 's6', NULL, '{"id": "crd.s6", "type": "card", "title": "6 小结", "outlinePath": "s6", "summary": "判断一条连接能不能成立，按顺序问五个问题：形状对不对、值域合不合适、统计量沿哪一维、梯度有没有通路、含义是不是那个意思。", "body": "判断一条连接能不能成立，按顺序问五个问题：形状对不对、值域合不合适、统计量沿哪一维、梯度有没有通路、含义是不是那个意思。前四个能用代码检查，第五个只能靠人判断 —— 而绝大多数「看起来能跑但结果不对」的问题，都出在第五个。", "chain": [], "crossLinks": [{"target": "crd.root-transformer", "targetKind": "card", "label": "Transformer 架构：从张量到概率", "weight": 1.0, "reason": "共享实体：张量形状"}, {"target": "crd.s1-2-relu", "targetKind": "card", "label": "1.2 ReLU", "weight": 0.71, "reason": "共享实体：张量形状"}, {"target": "crd.s2", "targetKind": "card", "label": "2 层与层之间的五种依赖", "weight": 0.71, "reason": "共享实体：张量形状"}, {"target": "crd.s2-1", "targetKind": "card", "label": "2.1 形状依赖", "weight": 0.5, "reason": "共享实体：张量形状"}, {"target": "crd.s2-4", "targetKind": "card", "label": "2.4 梯度路径依赖", "weight": 0.5, "reason": "共享实体：张量形状"}], "claimIds": []}');
