INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.ffn.linear-in-dim.4a3e', 'claim', 'Linear 层要求输入张量的最后一维等于权重的输入维度，否则矩阵乘无法进行。', 's1-1-linear', 'crd.s1-1-linear', 'verified', '{"id": "clm.arch.ffn.linear-in-dim.4a3e", "type": "claim", "statement": "Linear 层要求输入张量的最后一维等于权重的输入维度，否则矩阵乘无法进行。", "conditions": ["形状前提：x.shape[-1] == W.shape[1]", "前导维自由：x 的前导维可以是任意值，不参与约束"], "evidence": "输入 x 的形状通常是 (N, in_features)，权重 W 的形状是 (out_features, in_features)。", "breadth": {"outlinePath": "s1-1-linear", "cardId": "crd.s1-1-linear", "cardSummary": "Linear 层做的是仿射变换：y = x @ W.T + b。", "leafContent": "Linear 层做的是仿射变换：y = x @ W.T + b。"}, "depth": {"edges": ["edg.pre.14d21a"], "judgementPanel": {"question": "这个说法成立吗？", "expected": true, "reveal": {"explanation": "这个说法成立。原文依据：输入 x 的形状通常是 (N, in_features)，权重 W 的形状是 (out_features, in_features)。", "errorKinds": [{"kind": "shape", "why": "把 batch 维当成 in_features 是初学者最常见的错点。"}], "misconception": ""}}, "probeState": {"probe_status": "verified", "last_probed_at": null, "misconceptions": [], "confidence": 0.75, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.ffn.linear-param-batch.2fe7', 'claim', 'Linear 层的参数量与 batch 大小无关。', 's1-1-linear', 'crd.s1-1-linear', 'unprobed', '{"id": "clm.arch.ffn.linear-param-batch.2fe7", "type": "claim", "statement": "Linear 层的参数量与 batch 大小无关。", "conditions": ["W 的形状只由 in_features 与 out_features 决定", "计算量随 batch 线性增长，但参数量不变"], "evidence": "参数只有 W 和 b 两块，与 N 无关。", "breadth": {"outlinePath": "s1-1-linear", "cardId": "crd.s1-1-linear", "cardSummary": "Linear 层做的是仿射变换：y = x @ W.T + b。", "leafContent": "Linear 层做的是仿射变换：y = x @ W.T + b。"}, "depth": {"edges": [], "judgementPanel": {"question": "这个说法成立吗？", "expected": true, "reveal": {"explanation": "这个说法成立。原文依据：参数只有 W 和 b 两块，与 N 无关。", "errorKinds": [{"kind": "shape", "why": "把「计算量随 batch 增长」误当成「参数变多」。"}], "misconception": ""}}, "probeState": {"probe_status": "unprobed", "last_probed_at": null, "misconceptions": [], "confidence": 0.0, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.ffn.relu-shape.6092', 'claim', 'ReLU 是逐元素操作，不改变输入张量的形状。', 's1-2-relu', 'crd.s1-2-relu', 'mastered', '{"id": "clm.arch.ffn.relu-shape.6092", "type": "claim", "statement": "ReLU 是逐元素操作，不改变输入张量的形状。", "conditions": ["逐元素：输出形状与输入完全一致", "不引入需要对齐的新维度"], "evidence": "它不改变张量形状，只把负半轴压成 0。", "breadth": {"outlinePath": "s1-2-relu", "cardId": "crd.s1-2-relu", "cardSummary": "ReLU 是逐元素激活：max(0, x)。", "leafContent": "ReLU 是逐元素激活：max(0, x)。"}, "depth": {"edges": ["edg.dep.b141d0"], "judgementPanel": {"question": "这个说法成立吗？", "expected": true, "reveal": {"explanation": "这个说法成立。原文依据：它不改变张量形状，只把负半轴压成 0。", "errorKinds": [{"kind": "shape", "why": "误以为激活会改变通道数。"}], "misconception": ""}}, "probeState": {"probe_status": "mastered", "last_probed_at": null, "misconceptions": [], "confidence": 0.85, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.ffn.relu-zero-grad.8ab0', 'claim', '输入为负时 ReLU 的梯度为 0，该处参数在这一步不会更新。', 's1-2-relu', 'crd.s1-2-relu', 'confused', '{"id": "clm.arch.ffn.relu-zero-grad.8ab0", "type": "claim", "statement": "输入为负时 ReLU 的梯度为 0，该处参数在这一步不会更新。", "conditions": ["仅在 x<=0 的区间梯度为 0", "学习率再大也无法把死掉的神经元救回来"], "evidence": "输入为负时导数为 0，该神经元的参数在这一步不会更新。", "breadth": {"outlinePath": "s1-2-relu", "cardId": "crd.s1-2-relu", "cardSummary": "ReLU 是逐元素激活：max(0, x)。", "leafContent": "ReLU 是逐元素激活：max(0, x)。"}, "depth": {"edges": ["edg.aff.2366f8", "edg.ctr.daab6c"], "judgementPanel": {"question": "这个说法成立吗？", "expected": true, "reveal": {"explanation": "这个说法成立。原文依据：输入为负时导数为 0，该神经元的参数在这一步不会更新。", "errorKinds": [{"kind": "gradient", "why": "梯度为 0 与梯度很小的处置方式完全不同。"}], "misconception": "以为「梯度小」和「梯度为 0」是一回事，于是加大学习率试图救活。"}}, "probeState": {"probe_status": "confused", "last_probed_at": null, "misconceptions": ["以为「梯度小」和「梯度为 0」是一回事，于是加大学习率试图救活。"], "confidence": 0.3, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.ffn.relu-differentiable.a702', 'claim', 'ReLU 在整个实数域上处处可微。', 's1-2-relu', 'crd.s1-2-relu', 'unprobed', '{"id": "clm.arch.ffn.relu-differentiable.a702", "type": "claim", "statement": "ReLU 在整个实数域上处处可微。", "conditions": ["x=0 处左右导数不相等，导数不存在", "工程上取次梯度 0 或 1 只是约定，不是可微性"], "evidence": "输入为负时导数为 0；x=0 处左右导数分别为 0 与 1。", "breadth": {"outlinePath": "s1-2-relu", "cardId": "crd.s1-2-relu", "cardSummary": "ReLU 是逐元素激活：max(0, x)。", "leafContent": "ReLU 是逐元素激活：max(0, x)。"}, "depth": {"edges": ["edg.ctr.daab6c"], "judgementPanel": {"question": "这个说法成立吗？", "expected": false, "reveal": {"explanation": "这个说法不成立。原文依据：输入为负时导数为 0；x=0 处左右导数分别为 0 与 1。", "errorKinds": [{"kind": "gradient", "why": "框架能算梯度 ≠ 数学上可微。"}], "misconception": "因为有反向传播能跑通，就认为它处处可微。"}}, "probeState": {"probe_status": "unprobed", "last_probed_at": null, "misconceptions": ["因为有反向传播能跑通，就认为它处处可微。"], "confidence": 0.0, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.ffn.softmax-sum.a505', 'claim', 'Softmax 的输出沿类别维度求和为 1。', 's1-3-softmax', 'crd.s1-3-softmax', 'verified', '{"id": "clm.arch.ffn.softmax-sum.a505", "type": "claim", "statement": "Softmax 的输出沿类别维度求和为 1。", "conditions": ["求和必须沿类别维（通常是最后一维）", "若沿错误维度求和，得到的数不等于 1"], "evidence": "每一行求和为 1。", "breadth": {"outlinePath": "s1-3-softmax", "cardId": "crd.s1-3-softmax", "cardSummary": "Softmax 把一组实数压成概率分布：softmax(z)_i = exp(z_i) / sum_j exp(z_j)。", "leafContent": "Softmax 把一组实数压成概率分布：softmax(z)_i = exp(z_i) / sum_j exp(z_j)。"}, "depth": {"edges": ["edg.dep.e6b1e6"], "judgementPanel": {"question": "这个说法成立吗？", "expected": true, "reveal": {"explanation": "这个说法成立。原文依据：每一行求和为 1。", "errorKinds": [{"kind": "statistics", "why": "归约维度选错，形状对得上但语义全错。"}], "misconception": ""}}, "probeState": {"probe_status": "verified", "last_probed_at": null, "misconceptions": [], "confidence": 0.75, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.ffn.softmax-dim.4af1', 'claim', '多分类场景下 Softmax 沿类别维（通常是最后一维）归一化，而不是 batc', 's1-3-softmax', 'crd.s1-3-softmax', 'unprobed', '{"id": "clm.arch.ffn.softmax-dim.4af1", "type": "claim", "statement": "多分类场景下 Softmax 沿类别维（通常是最后一维）归一化，而不是 batch 维。", "conditions": ["dim 参数默认取最后一维", "沿 batch 维归一化会破坏样本之间的独立性"], "evidence": "它沿类别维归约，输出与输入同形。", "breadth": {"outlinePath": "s1-3-softmax", "cardId": "crd.s1-3-softmax", "cardSummary": "Softmax 把一组实数压成概率分布：softmax(z)_i = exp(z_i) / sum_j exp(z_j)。", "leafContent": "Softmax 把一组实数压成概率分布：softmax(z)_i = exp(z_i) / sum_j exp(z_j)。"}, "depth": {"edges": ["edg.aff.8c0164", "edg.dep.e6b1e6"], "judgementPanel": {"question": "这个说法成立吗？", "expected": true, "reveal": {"explanation": "这个说法成立。原文依据：它沿类别维归约，输出与输入同形。", "errorKinds": [{"kind": "statistics", "why": "归一化维度选错，是「形状没问题但结果全错」的典型。"}], "misconception": ""}}, "probeState": {"probe_status": "unprobed", "last_probed_at": null, "misconceptions": [], "confidence": 0.0, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.ffn.softmax-shift.6358', 'claim', '给所有 logits 加上同一个常数，Softmax 的输出不变。', 's1-3-softmax', 'crd.s1-3-softmax', 'unprobed', '{"id": "clm.arch.ffn.softmax-shift.6358", "type": "claim", "statement": "给所有 logits 加上同一个常数，Softmax 的输出不变。", "conditions": ["数学上严格成立，与常数大小无关", "数值实现上减去最大值正是利用这一性质防溢出"], "evidence": "整体平移不变。给所有 logits 加同一个常数，输出完全不变。", "breadth": {"outlinePath": "s1-3-softmax", "cardId": "crd.s1-3-softmax", "cardSummary": "Softmax 把一组实数压成概率分布：softmax(z)_i = exp(z_i) / sum_j exp(z_j)。", "leafContent": "Softmax 把一组实数压成概率分布：softmax(z)_i = exp(z_i) / sum_j exp(z_j)。"}, "depth": {"edges": ["edg.dep.ac6e04"], "judgementPanel": {"question": "这个说法成立吗？", "expected": true, "reveal": {"explanation": "这个说法成立。原文依据：整体平移不变。给所有 logits 加同一个常数，输出完全不变。", "errorKinds": [{"kind": "range", "why": "误以为加常数会整体抬高概率。"}], "misconception": ""}}, "probeState": {"probe_status": "unprobed", "last_probed_at": null, "misconceptions": [], "confidence": 0.0, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.ffn.ce-logits.5a91', 'claim', 'CrossEntropy 期望接收未归一化的 logits，内部已完成 log-', 's1-4', 'crd.s1-4', 'unprobed', '{"id": "clm.arch.ffn.ce-logits.5a91", "type": "claim", "statement": "CrossEntropy 期望接收未归一化的 logits，内部已完成 log-softmax。", "conditions": ["输入是 logits，不是概率", "内部用 log-sum-exp 稳定实现"], "evidence": "CrossEntropy 接收的是未归一化的 logits，内部已经做了 log-softmax。", "breadth": {"outlinePath": "s1-4", "cardId": "crd.s1-4", "cardSummary": "CrossEntropy 接收的是未归一化的 logits，内部已经做了 log-softmax。", "leafContent": "CrossEntropy 接收的是未归一化的 logits，内部已经做了 log-softmax。"}, "depth": {"edges": ["edg.dep.ac6e04", "edg.ref.c1339e"], "judgementPanel": {"question": "这个说法成立吗？", "expected": true, "reveal": {"explanation": "这个说法成立。原文依据：CrossEntropy 接收的是未归一化的 logits，内部已经做了 log-softmax。", "errorKinds": [{"kind": "range", "why": "把「概率」当成输入，等价于多做了一次归一化。"}], "misconception": ""}}, "probeState": {"probe_status": "unprobed", "last_probed_at": null, "misconceptions": [], "confidence": 0.0, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.ffn.ce-double-softmax.eed8', 'claim', '先做 Softmax 再送 CrossEntropy，与直接送 logits 完', 's1-4', 'crd.s1-4', 'confused', '{"id": "clm.arch.ffn.ce-double-softmax.eed8", "type": "claim", "statement": "先做 Softmax 再送 CrossEntropy，与直接送 logits 完全等价。", "conditions": ["输出值接近但梯度不同", "梯度被额外乘上 p(1-p)，收敛显著变慢"], "evidence": "先 Softmax 再送 CrossEntropy，数学上不等于直接送 logits。", "breadth": {"outlinePath": "s1-4", "cardId": "crd.s1-4", "cardSummary": "CrossEntropy 接收的是未归一化的 logits，内部已经做了 log-softmax。", "leafContent": "CrossEntropy 接收的是未归一化的 logits，内部已经做了 log-softmax。"}, "depth": {"edges": ["edg.ref.c1339e"], "judgementPanel": {"question": "这个说法成立吗？", "expected": false, "reveal": {"explanation": "这个说法不成立。原文依据：先 Softmax 再送 CrossEntropy，数学上不等于直接送 logits。", "errorKinds": [{"kind": "gradient", "why": "错点不在前向数值，而在反向梯度。"}], "misconception": "只看 loss 数值接近，就认为两者等价，忽略梯度被压缩。"}}, "probeState": {"probe_status": "confused", "last_probed_at": null, "misconceptions": ["只看 loss 数值接近，就认为两者等价，忽略梯度被压缩。"], "confidence": 0.3, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.dep.shape.85dd', 'claim', '形状依赖只要求上游输出的最后一维等于下游期望的输入维度。', 's2-1', 'crd.s2-1', 'unprobed', '{"id": "clm.arch.dep.shape.85dd", "type": "claim", "statement": "形状依赖只要求上游输出的最后一维等于下游期望的输入维度。", "conditions": ["逐元素操作不改变形状，天然满足", "需要改变最后一维的操作（如 Linear）必须显式对齐"], "evidence": "上游输出的最后一维，必须等于下游期望的输入维度。", "breadth": {"outlinePath": "s2-1", "cardId": "crd.s2-1", "cardSummary": "张量形状是最容易检查的一层：上游输出的最后一维，必须等于下游期望的输入维。", "leafContent": "张量形状是最容易检查的一层：上游输出的最后一维，必须等于下游期望的输入维。"}, "depth": {"edges": ["edg.ctr.47718c", "edg.pre.14d21a"], "judgementPanel": {"question": "这个说法成立吗？", "expected": true, "reveal": {"explanation": "这个说法成立。原文依据：上游输出的最后一维，必须等于下游期望的输入维度。", "errorKinds": [{"kind": "shape", "why": "只看总元素个数相等，就以为形状可以接。"}], "misconception": ""}}, "probeState": {"probe_status": "unprobed", "last_probed_at": null, "misconceptions": [], "confidence": 0.0, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.dep.range-sigmoid.0888', 'claim', 'Sigmoid 的输出恒为正且落在 (0,1)，二分类可直接作为概率使用。', 's2-2', 'crd.s2-2', 'unprobed', '{"id": "clm.arch.dep.range-sigmoid.0888", "type": "claim", "statement": "Sigmoid 的输出恒为正且落在 (0,1)，二分类可直接作为概率使用。", "conditions": ["二分类且两类互斥时成立", "多分类下各类之和不为 1，不能直接当分布"], "evidence": "Sigmoid 输出恒为正且落在 (0,1)。", "breadth": {"outlinePath": "s2-2", "cardId": "crd.s2-2", "cardSummary": "值域依赖问的是输出取值范围是否符合下游假设。", "leafContent": "值域依赖问的是输出取值范围是否符合下游假设。"}, "depth": {"edges": [], "judgementPanel": {"question": "这个说法成立吗？", "expected": true, "reveal": {"explanation": "这个说法成立。原文依据：Sigmoid 输出恒为正且落在 (0,1)。", "errorKinds": [{"kind": "range", "why": "把二分类的结论套到多分类上。"}], "misconception": ""}}, "probeState": {"probe_status": "unprobed", "last_probed_at": null, "misconceptions": [], "confidence": 0.0, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.dep.stats-dim.e92b', 'claim', 'LayerNorm 在特征维上计算均值和方差，与 batch 大小无关。', 's2-3', 'crd.s2-3', 'unprobed', '{"id": "clm.arch.dep.stats-dim.e92b", "type": "claim", "statement": "LayerNorm 在特征维上计算均值和方差，与 batch 大小无关。", "conditions": ["归一化维度是最后一维（特征维）", "因此单样本也能稳定计算"], "evidence": "LayerNorm 在特征维上算，与 batch 无关。", "breadth": {"outlinePath": "s2-3", "cardId": "crd.s2-3", "cardSummary": "LayerNorm 与 BatchNorm 的差别不在公式，而在沿哪一维算统计量：LayerNorm 在特征维上算，与 batch 无关；Bat…", "leafContent": "LayerNorm 与 BatchNorm 的差别不在公式，而在沿哪一维算统计量：LayerNorm 在特征维上算，与 batch 无关；BatchNorm 在 batch 维上算，batch 太小统计量就不可靠。"}, "depth": {"edges": ["edg.ctr.1c8d20"], "judgementPanel": {"question": "这个说法成立吗？", "expected": true, "reveal": {"explanation": "这个说法成立。原文依据：LayerNorm 在特征维上算，与 batch 无关。", "errorKinds": [{"kind": "statistics", "why": "把 LayerNorm 当成「按 batch 求均值」。"}], "misconception": ""}}, "probeState": {"probe_status": "unprobed", "last_probed_at": null, "misconceptions": [], "confidence": 0.0, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.dep.bn-small-batch.b33d', 'claim', 'BatchNorm 在 batch=1 时依然稳定。', 's2-3', 'crd.s2-3', 'unprobed', '{"id": "clm.arch.dep.bn-small-batch.b33d", "type": "claim", "statement": "BatchNorm 在 batch=1 时依然稳定。", "conditions": ["batch=1 时批内方差为 0，归一化退化为减均值", "训练方差估计严重失真"], "evidence": "BatchNorm 在 batch 维上算，batch 太小统计量就不可靠。", "breadth": {"outlinePath": "s2-3", "cardId": "crd.s2-3", "cardSummary": "LayerNorm 与 BatchNorm 的差别不在公式，而在沿哪一维算统计量：LayerNorm 在特征维上算，与 batch 无关；Bat…", "leafContent": "LayerNorm 与 BatchNorm 的差别不在公式，而在沿哪一维算统计量：LayerNorm 在特征维上算，与 batch 无关；BatchNorm 在 batch 维上算，batch 太小统计量就不可靠。"}, "depth": {"edges": ["edg.ctr.1c8d20"], "judgementPanel": {"question": "这个说法成立吗？", "expected": false, "reveal": {"explanation": "这个说法不成立。原文依据：BatchNorm 在 batch 维上算，batch 太小统计量就不可靠。", "errorKinds": [{"kind": "statistics", "why": "混淆「训练时的批内统计量」与「推理时的滑动统计量」。"}], "misconception": "以为 BatchNorm 有自己的滑动统计量兜底，所以任意 batch 都行。"}}, "probeState": {"probe_status": "unprobed", "last_probed_at": null, "misconceptions": ["以为 BatchNorm 有自己的滑动统计量兜底，所以任意 batch 都行。"], "confidence": 0.0, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.dep.grad-residual.8054', 'claim', '残差连接的恒等捷径要求主分支输出与捷径输入形状一致。', 's2-4', 'crd.s2-4', 'unprobed', '{"id": "clm.arch.dep.grad-residual.8054", "type": "claim", "statement": "残差连接的恒等捷径要求主分支输出与捷径输入形状一致。", "conditions": ["形状一致时可直接相加", "不一致时必须加投影（1x1 卷积或 Linear）对齐"], "evidence": "残差要求主分支与捷径形状一致。", "breadth": {"outlinePath": "s2-4", "cardId": "crd.s2-4", "cardSummary": "梯度路径依赖问的是梯度能不能从下游回传到上游。", "leafContent": "梯度路径依赖问的是梯度能不能从下游回传到上游。"}, "depth": {"edges": ["edg.pre.8eef96"], "judgementPanel": {"question": "这个说法成立吗？", "expected": true, "reveal": {"explanation": "这个说法成立。原文依据：残差要求主分支与捷径形状一致。", "errorKinds": [{"kind": "shape", "why": "忽略通道数变化，直接相加导致形状报错或广播错误。"}], "misconception": ""}}, "probeState": {"probe_status": "unprobed", "last_probed_at": null, "misconceptions": [], "confidence": 0.0, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.dep.grad-relu-dead.ebf3', 'claim', 'ReLU 的死区会切断该神经元的梯度通道，使其参数不再更新。', 's2-4', 'crd.s2-4', 'unprobed', '{"id": "clm.arch.dep.grad-relu-dead.ebf3", "type": "claim", "statement": "ReLU 的死区会切断该神经元的梯度通道，使其参数不再更新。", "conditions": ["输入长期为负才会形成死区", "使用 LeakyReLU 或 GELU 可缓解"], "evidence": "输入为负时导数为 0。", "breadth": {"outlinePath": "s2-4", "cardId": "crd.s2-4", "cardSummary": "梯度路径依赖问的是梯度能不能从下游回传到上游。", "leafContent": "梯度路径依赖问的是梯度能不能从下游回传到上游。"}, "depth": {"edges": ["edg.aff.2366f8"], "judgementPanel": {"question": "这个说法成立吗？", "expected": true, "reveal": {"explanation": "这个说法成立。原文依据：输入为负时导数为 0。", "errorKinds": [{"kind": "gradient", "why": "以为是学习率太小，实际是梯度恒为 0。"}], "misconception": ""}}, "probeState": {"probe_status": "unprobed", "last_probed_at": null, "misconceptions": [], "confidence": 0.0, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.dep.semantic.7874', 'claim', '只要形状能对上，接什么层在语义上都是正确的。', 's2-5', 'crd.s2-5', 'unprobed', '{"id": "clm.arch.dep.semantic.7874", "type": "claim", "statement": "只要形状能对上，接什么层在语义上都是正确的。", "conditions": ["形状相容只是必要条件，不是充分条件", "语义依赖要求下游对输入的统计含义有明确假设"], "evidence": "形状对得上、值域也合适，但含义不对。", "breadth": {"outlinePath": "s2-5", "cardId": "crd.s2-5", "cardSummary": "语义依赖是最隐蔽的一层：形状对得上、值域也合适，但含义不对。", "leafContent": "语义依赖是最隐蔽的一层：形状对得上、值域也合适，但含义不对。"}, "depth": {"edges": ["edg.ctr.47718c", "edg.ref.e76580"], "judgementPanel": {"question": "这个说法成立吗？", "expected": false, "reveal": {"explanation": "这个说法不成立。原文依据：形状对得上、值域也合适，但含义不对。", "errorKinds": [{"kind": "semantic", "why": "框架只检查形状，不检查语义。"}], "misconception": "用「没报错」当作「接对了」的证据。"}}, "probeState": {"probe_status": "unprobed", "last_probed_at": null, "misconceptions": ["用「没报错」当作「接对了」的证据。"], "confidence": 0.0, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.dep.relu-then-softmax.d07e', 'claim', 'ReLU 之后可以直接接 Softmax 输出类别概率。', 's2-5', 'crd.s2-5', 'confused', '{"id": "clm.arch.dep.relu-then-softmax.d07e", "type": "claim", "statement": "ReLU 之后可以直接接 Softmax 输出类别概率。", "conditions": ["形状依赖满足：ReLU 不改变形状，Softmax 接受同形输入", "语义依赖不满足：Softmax 期望未归一化 logits，ReLU 输出全非负，负半轴信息已丢", "边界：C=1 时 Softmax 恒输出 1，完全没有区分度"], "evidence": "形状完全相容，可 ReLU 的输出不是 logits。", "breadth": {"outlinePath": "s2-5", "cardId": "crd.s2-5", "cardSummary": "语义依赖是最隐蔽的一层：形状对得上、值域也合适，但含义不对。", "leafContent": "语义依赖是最隐蔽的一层：形状对得上、值域也合适，但含义不对。"}, "depth": {"edges": ["edg.aff.8c0164", "edg.dep.b141d0", "edg.ref.e76580"], "judgementPanel": {"question": "这个说法成立吗？", "expected": false, "reveal": {"explanation": "这个说法不成立。原文依据：形状完全相容，可 ReLU 的输出不是 logits。", "errorKinds": [{"kind": "semantic", "why": "错点落在语义依赖，而不是形状或值域。"}], "misconception": "看到形状能跑通、loss 也在降，就认定这条连接成立。"}}, "probeState": {"probe_status": "confused", "last_probed_at": null, "misconceptions": ["看到形状能跑通、loss 也在降，就认定这条连接成立。"], "confidence": 0.3, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.train.ln-dim.8cae', 'claim', 'LayerNorm 的归一化统计量在单个样本内部沿特征维计算。', 's3-1-layernorm-batchnorm', 'crd.s3-1-layernorm-batchnorm', 'unprobed', '{"id": "clm.arch.train.ln-dim.8cae", "type": "claim", "statement": "LayerNorm 的归一化统计量在单个样本内部沿特征维计算。", "conditions": ["与 batch 大小无关", "序列模型中不必担心变长导致的统计量漂移"], "evidence": "LayerNorm 在单样本内部沿特征维归一化。", "breadth": {"outlinePath": "s3-1-layernorm-batchnorm", "cardId": "crd.s3-1-layernorm-batchnorm", "cardSummary": "两者的公式几乎一样，差别只在统计量的来源。", "leafContent": "两者的公式几乎一样，差别只在统计量的来源。"}, "depth": {"edges": [], "judgementPanel": {"question": "这个说法成立吗？", "expected": true, "reveal": {"explanation": "这个说法成立。原文依据：LayerNorm 在单样本内部沿特征维归一化。", "errorKinds": [{"kind": "statistics", "why": "把 LayerNorm 当成「按 batch 归一化」。"}], "misconception": ""}}, "probeState": {"probe_status": "unprobed", "last_probed_at": null, "misconceptions": [], "confidence": 0.0, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.train.bn-infer.7ae7', 'claim', 'BatchNorm 在推理阶段使用训练期累积的滑动统计量，而不是当前 batch', 's3-1-layernorm-batchnorm', 'crd.s3-1-layernorm-batchnorm', 'unprobed', '{"id": "clm.arch.train.bn-infer.7ae7", "type": "claim", "statement": "BatchNorm 在推理阶段使用训练期累积的滑动统计量，而不是当前 batch 的统计量。", "conditions": ["训练与推理行为不同，切换必须显式调用 eval 模式", "忘记切 eval 会导致推理结果随 batch 组成变化"], "evidence": "推理时改用训练期累积的滑动统计量。", "breadth": {"outlinePath": "s3-1-layernorm-batchnorm", "cardId": "crd.s3-1-layernorm-batchnorm", "cardSummary": "两者的公式几乎一样，差别只在统计量的来源。", "leafContent": "两者的公式几乎一样，差别只在统计量的来源。"}, "depth": {"edges": [], "judgementPanel": {"question": "这个说法成立吗？", "expected": true, "reveal": {"explanation": "这个说法成立。原文依据：推理时改用训练期累积的滑动统计量。", "errorKinds": [{"kind": "statistics", "why": "忘了切换 eval 模式，是线上精度掉点的常见原因。"}], "misconception": ""}}, "probeState": {"probe_status": "unprobed", "last_probed_at": null, "misconceptions": [], "confidence": 0.0, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.train.residual-shape.b560', 'claim', '残差相加前，主分支输出与捷径必须同形状。', 's3-2', 'crd.s3-2', 'unprobed', '{"id": "clm.arch.train.residual-shape.b560", "type": "claim", "statement": "残差相加前，主分支输出与捷径必须同形状。", "conditions": ["同形状可直接相加", "通道数变化时需投影对齐"], "evidence": "主分支输出与捷径必须同形状。", "breadth": {"outlinePath": "s3-2", "cardId": "crd.s3-2", "cardSummary": "残差连接把 y = F(x) + x 写进结构里，一方面让梯度有恒等通路，另一方面让网络学「增量」而不是「全量」。", "leafContent": "残差连接把 y = F(x) + x 写进结构里，一方面让梯度有恒等通路，另一方面让网络学「增量」而不是「全量」。"}, "depth": {"edges": ["edg.pre.8eef96"], "judgementPanel": {"question": "这个说法成立吗？", "expected": true, "reveal": {"explanation": "这个说法成立。原文依据：主分支输出与捷径必须同形状。", "errorKinds": [{"kind": "shape", "why": "通道数改变后忘记加投影。"}], "misconception": ""}}, "probeState": {"probe_status": "unprobed", "last_probed_at": null, "misconceptions": [], "confidence": 0.0, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.train.pre-ln.b81c', 'claim', '相比 Post-LN，Pre-LN 让残差通路保持无归一化，深层训练更稳定。', 's3-3-pre-ln-post-ln', 'crd.s3-3-pre-ln-post-ln', 'unprobed', '{"id": "clm.arch.train.pre-ln.b81c", "type": "claim", "statement": "相比 Post-LN，Pre-LN 让残差通路保持无归一化，深层训练更稳定。", "conditions": ["深层（数十层）时差异显著", "浅层网络两者差别不大"], "evidence": "Pre-LN 把归一化放在子层之前，残差通路上没有任何归一化。", "breadth": {"outlinePath": "s3-3-pre-ln-post-ln", "cardId": "crd.s3-3-pre-ln-post-ln", "cardSummary": "Pre-LN 把归一化放在子层之前，残差通路上没有任何归一化，梯度可以无损回传；Post-LN 把归一化放在残差相加之后，深层网络训练更依赖 w…", "leafContent": "Pre-LN 把归一化放在子层之前，残差通路上没有任何归一化，梯度可以无损回传；Post-LN 把归一化放在残差相加之后，深层网络训练更依赖 warmup。"}, "depth": {"edges": ["edg.ctr.a7e9dd"], "judgementPanel": {"question": "这个说法成立吗？", "expected": true, "reveal": {"explanation": "这个说法成立。原文依据：Pre-LN 把归一化放在子层之前，残差通路上没有任何归一化。", "errorKinds": [{"kind": "gradient", "why": "只看单层公式，忽略残差通路上是否夹了归一化。"}], "misconception": ""}}, "probeState": {"probe_status": "unprobed", "last_probed_at": null, "misconceptions": [], "confidence": 0.0, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.train.post-ln-deep.d2c5', 'claim', 'Post-LN 在深层网络中不需要 warmup 也能稳定收敛。', 's3-3-pre-ln-post-ln', 'crd.s3-3-pre-ln-post-ln', 'unprobed', '{"id": "clm.arch.train.post-ln-deep.d2c5", "type": "claim", "statement": "Post-LN 在深层网络中不需要 warmup 也能稳定收敛。", "conditions": ["残差通路上夹了归一化，梯度尺度随深度累积", "实践中通常需要 warmup 与更小的初始学习率"], "evidence": "Post-LN 把归一化放在残差相加之后，深层网络训练更依赖 warmup。", "breadth": {"outlinePath": "s3-3-pre-ln-post-ln", "cardId": "crd.s3-3-pre-ln-post-ln", "cardSummary": "Pre-LN 把归一化放在子层之前，残差通路上没有任何归一化，梯度可以无损回传；Post-LN 把归一化放在残差相加之后，深层网络训练更依赖 w…", "leafContent": "Pre-LN 把归一化放在子层之前，残差通路上没有任何归一化，梯度可以无损回传；Post-LN 把归一化放在残差相加之后，深层网络训练更依赖 warmup。"}, "depth": {"edges": ["edg.ctr.a7e9dd"], "judgementPanel": {"question": "这个说法成立吗？", "expected": false, "reveal": {"explanation": "这个说法不成立。原文依据：Post-LN 把归一化放在残差相加之后，深层网络训练更依赖 warmup。", "errorKinds": [{"kind": "gradient", "why": "错点在深层梯度尺度，不在单层实现。"}], "misconception": "把「浅层能跑通」当成「深层也没问题」。"}}, "probeState": {"probe_status": "unprobed", "last_probed_at": null, "misconceptions": ["把「浅层能跑通」当成「深层也没问题」。"], "confidence": 0.0, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.attn.scale.2883', 'claim', '除以 sqrt(d_k) 是为了控制点积方差，避免 Softmax 进入饱和区。', 's4-1', 'crd.s4-1', 'unprobed', '{"id": "clm.arch.attn.scale.2883", "type": "claim", "statement": "除以 sqrt(d_k) 是为了控制点积方差，避免 Softmax 进入饱和区。", "conditions": ["假设 q、k 各分量独立且方差为 1，点积方差约为 d_k", "d_k 很小时不缩放影响有限"], "evidence": "点积的方差随 d_k 线性增长。", "breadth": {"outlinePath": "s4-1", "cardId": "crd.s4-1", "cardSummary": "缩放点积注意力是 softmax(QK^T / sqrt(d_k)) V。", "leafContent": "缩放点积注意力是 softmax(QK^T / sqrt(d_k)) V。"}, "depth": {"edges": ["edg.ref.747adc"], "judgementPanel": {"question": "这个说法成立吗？", "expected": true, "reveal": {"explanation": "这个说法成立。原文依据：点积的方差随 d_k 线性增长。", "errorKinds": [{"kind": "statistics", "why": "把缩放当成「调参技巧」，不知道它对应方差量级。"}], "misconception": ""}}, "probeState": {"probe_status": "unprobed", "last_probed_at": null, "misconceptions": [], "confidence": 0.0, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.attn.no-scale.1418', 'claim', '不除以 sqrt(d_k)，注意力分布只会更尖锐，模型效果更好。', 's4-1', 'crd.s4-1', 'unprobed', '{"id": "clm.arch.attn.no-scale.1418", "type": "claim", "statement": "不除以 sqrt(d_k)，注意力分布只会更尖锐，模型效果更好。", "conditions": ["分布更尖锐 → Softmax 饱和 → 梯度接近 0", "d_k 越大问题越严重"], "evidence": "不缩放会让 Softmax 进入饱和区，梯度接近 0。", "breadth": {"outlinePath": "s4-1", "cardId": "crd.s4-1", "cardSummary": "缩放点积注意力是 softmax(QK^T / sqrt(d_k)) V。", "leafContent": "缩放点积注意力是 softmax(QK^T / sqrt(d_k)) V。"}, "depth": {"edges": ["edg.ref.747adc"], "judgementPanel": {"question": "这个说法成立吗？", "expected": false, "reveal": {"explanation": "这个说法不成立。原文依据：不缩放会让 Softmax 进入饱和区，梯度接近 0。", "errorKinds": [{"kind": "statistics", "why": "尖锐不等于准确，饱和会让梯度消失。"}], "misconception": "把「注意力更集中」当成「注意力更准」。"}}, "probeState": {"probe_status": "unprobed", "last_probed_at": null, "misconceptions": ["把「注意力更集中」当成「注意力更准」。"], "confidence": 0.0, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.attn.mask-before-softmax.f3c1', 'claim', '因果掩码必须在 Softmax 之前把被屏蔽位置的得分置为 -inf。', 's4-2', 'crd.s4-2', 'unprobed', '{"id": "clm.arch.attn.mask-before-softmax.f3c1", "type": "claim", "statement": "因果掩码必须在 Softmax 之前把被屏蔽位置的得分置为 -inf。", "conditions": ["掩码要参与归一化的分母", "用 -inf 而不是 0，才能让 exp 后严格为 0"], "evidence": "必须在 Softmax 之前把未来位置置为 -inf。", "breadth": {"outlinePath": "s4-2", "cardId": "crd.s4-2", "cardSummary": "因果掩码必须在 Softmax 之前把未来位置置为 -inf。", "leafContent": "因果掩码必须在 Softmax 之前把未来位置置为 -inf。"}, "depth": {"edges": ["edg.ctr.83bbb5"], "judgementPanel": {"question": "这个说法成立吗？", "expected": true, "reveal": {"explanation": "这个说法成立。原文依据：必须在 Softmax 之前把未来位置置为 -inf。", "errorKinds": [{"kind": "statistics", "why": "以为「乘 0 就等于屏蔽」。"}], "misconception": ""}}, "probeState": {"probe_status": "unprobed", "last_probed_at": null, "misconceptions": [], "confidence": 0.0, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.attn.mask-after.ca87', 'claim', '先做 Softmax，再把未来位置乘 0，与先掩码效果相同。', 's4-2', 'crd.s4-2', 'unprobed', '{"id": "clm.arch.attn.mask-after.ca87", "type": "claim", "statement": "先做 Softmax，再把未来位置乘 0，与先掩码效果相同。", "conditions": ["乘 0 之前，未来位置已经占据了分母的概率质量", "归一化被污染，剩余概率之和小于 1"], "evidence": "先 Softmax 再乘 0 不等价。", "breadth": {"outlinePath": "s4-2", "cardId": "crd.s4-2", "cardSummary": "因果掩码必须在 Softmax 之前把未来位置置为 -inf。", "leafContent": "因果掩码必须在 Softmax 之前把未来位置置为 -inf。"}, "depth": {"edges": ["edg.ctr.83bbb5"], "judgementPanel": {"question": "这个说法成立吗？", "expected": false, "reveal": {"explanation": "这个说法不成立。原文依据：先 Softmax 再乘 0 不等价。", "errorKinds": [{"kind": "statistics", "why": "错点在归一化分母，不在输出值本身。"}], "misconception": "只检查「未来位置输出是不是 0」，不检查概率之和。"}}, "probeState": {"probe_status": "unprobed", "last_probed_at": null, "misconceptions": ["只检查「未来位置输出是不是 0」，不检查概率之和。"], "confidence": 0.0, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.attn.mha-concat.cffd', 'claim', '多头注意力的各头输出先拼接，再经过一次线性投影。', 's4-3', 'crd.s4-3', 'unprobed', '{"id": "clm.arch.attn.mha-concat.cffd", "type": "claim", "statement": "多头注意力的各头输出先拼接，再经过一次线性投影。", "conditions": ["拼接后的维度回到 d_model", "投影矩阵负责融合各头信息"], "evidence": "最后拼接再做一次线性投影。", "breadth": {"outlinePath": "s4-3", "cardId": "crd.s4-3", "cardSummary": "多头注意力把 d_model 切成 h 份并行做注意力，每个头在自己的子空间里学一种关系模式，最后拼接再做一次线性投影。", "leafContent": "多头注意力把 d_model 切成 h 份并行做注意力，每个头在自己的子空间里学一种关系模式，最后拼接再做一次线性投影。"}, "depth": {"edges": ["edg.ref.89c977"], "judgementPanel": {"question": "这个说法成立吗？", "expected": true, "reveal": {"explanation": "这个说法成立。原文依据：最后拼接再做一次线性投影。", "errorKinds": [{"kind": "shape", "why": "忘记最后的投影，维度对不上或信息无法融合。"}], "misconception": ""}}, "probeState": {"probe_status": "unprobed", "last_probed_at": null, "misconceptions": [], "confidence": 0.0, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.attn.mha-heads-independent.b0da', 'claim', '多头注意力中各个头是完全独立的模型，互不共享输入。', 's4-3', 'crd.s4-3', 'unprobed', '{"id": "clm.arch.attn.mha-heads-independent.b0da", "type": "claim", "statement": "多头注意力中各个头是完全独立的模型，互不共享输入。", "conditions": ["各头共享同一份输入，只是投影矩阵不同", "头数增加不改变总参数量级（d_model 被切分）"], "evidence": "把 d_model 切成 h 份并行做注意力。", "breadth": {"outlinePath": "s4-3", "cardId": "crd.s4-3", "cardSummary": "多头注意力把 d_model 切成 h 份并行做注意力，每个头在自己的子空间里学一种关系模式，最后拼接再做一次线性投影。", "leafContent": "多头注意力把 d_model 切成 h 份并行做注意力，每个头在自己的子空间里学一种关系模式，最后拼接再做一次线性投影。"}, "depth": {"edges": ["edg.ref.89c977"], "judgementPanel": {"question": "这个说法成立吗？", "expected": false, "reveal": {"explanation": "这个说法不成立。原文依据：把 d_model 切成 h 份并行做注意力。", "errorKinds": [{"kind": "shape", "why": "混淆「切分子空间」与「复制模型」。"}], "misconception": "把头当成多个独立小模型，以为参数量随头数翻倍。"}}, "probeState": {"probe_status": "unprobed", "last_probed_at": null, "misconceptions": ["把头当成多个独立小模型，以为参数量随头数翻倍。"], "confidence": 0.0, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.attn.pos-encoding-needed.3780', 'claim', '纯自注意力对位置不敏感，必须额外注入位置信息才能区分顺序。', 's4-4', 'crd.s4-4', 'unprobed', '{"id": "clm.arch.attn.pos-encoding-needed.3780", "type": "claim", "statement": "纯自注意力对位置不敏感，必须额外注入位置信息才能区分顺序。", "conditions": ["自注意力是置换等变的", "位置编码可以是绝对式、相对式或 RoPE，形式不影响结论"], "evidence": "自注意力对输入顺序是置换等变的。", "breadth": {"outlinePath": "s4-4", "cardId": "crd.s4-4", "cardSummary": "自注意力对输入顺序是置换等变的：把 token 打乱，输出只是跟着打乱，模型本身感知不到「谁在前」。", "leafContent": "自注意力对输入顺序是置换等变的：把 token 打乱，输出只是跟着打乱，模型本身感知不到「谁在前」。"}, "depth": {"edges": [], "judgementPanel": {"question": "这个说法成立吗？", "expected": true, "reveal": {"explanation": "这个说法成立。原文依据：自注意力对输入顺序是置换等变的。", "errorKinds": [{"kind": "semantic", "why": "以为「注意力看得到所有 token」就等于「知道顺序」。"}], "misconception": ""}}, "probeState": {"probe_status": "unprobed", "last_probed_at": null, "misconceptions": [], "confidence": 0.0, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.s5.boundary.92a4', 'claim', '速查表里的判断句只在写明的边界内成立，脱离边界直接套用会判错。', 's5', 'crd.s5', 'unprobed', '{"id": "clm.arch.s5.boundary.92a4", "type": "claim", "statement": "速查表里的判断句只在写明的边界内成立，脱离边界直接套用会判错。", "conditions": ["每条判断句都附一条边界说明：什么情况下结论翻转", "把「成立」当成无条件成立，等于丢掉了这一列"], "evidence": "第三条「边界」说明什么情况下结论会翻转 —— 这一列就是深度图谱里「条件」的来源。", "breadth": {"outlinePath": "s5", "cardId": "crd.s5", "cardSummary": "下面这张表是判断题形式的速查清单，用于快速自测。", "leafContent": "下面这张表是判断题形式的速查清单，用于快速自测。"}, "depth": {"edges": [], "judgementPanel": {"question": "这个说法成立吗？", "expected": true, "reveal": {"explanation": "成立。速查表把每条判断句与它的边界并列写出来，就是为了说明「成立」是有前提的：BatchNorm 那条要求显式切到 eval，交叉熵那条要求损失内部做了 log-softmax，前提一变结论就翻转。", "errorKinds": [{"kind": "semantic", "why": "把「结论成立」直接当成「无条件成立」，边界那一列被当成了注解而不是条件。"}], "misconception": ""}}, "probeState": {"probe_status": "unprobed", "last_probed_at": null, "misconceptions": [], "confidence": 0.0, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.qa.q2.2899', 'claim', 'Dropout 在推理阶段仍需随机置零', 's5-1', 'crd.s5-1', 'unprobed', '{"id": "clm.arch.qa.q2.2899", "type": "claim", "statement": "Dropout 在推理阶段仍需随机置零", "conditions": ["边界：推理阶段关闭，训练阶段才随机置零"], "evidence": "判断题表：Dropout 在推理阶段仍需随机置零 —— 不成立", "breadth": {"outlinePath": "s5-1", "cardId": "crd.s5-1", "cardSummary": "ReLU 在整个实数域上处处可微；不成立；x=0 处左右导数不等", "leafContent": "ReLU 在整个实数域上处处可微；不成立；x=0 处左右导数不等"}, "depth": {"edges": [], "judgementPanel": {"question": "这个说法成立吗？", "expected": false, "reveal": {"explanation": "这个说法不成立。原文依据：判断题表：Dropout 在推理阶段仍需随机置零 —— 不成立", "errorKinds": [{"kind": "semantic", "why": "表格判断题未标注错点类型，按语义依赖处理"}], "misconception": ""}}, "probeState": {"probe_status": "unprobed", "last_probed_at": null, "misconceptions": [], "confidence": 0.0, "attempts": 0, "correct": 0}}}');
