INSERT OR REPLACE INTO kg_node (id, kind, title, path, parent_id, probe_status, payload) VALUES ('clm.arch.qa.q6.55d7', 'claim', 'Softmax 的输出可以直接当作模型置信度使用', 's5-1', 'crd.s5-1', 'unprobed', '{"id": "clm.arch.qa.q6.55d7", "type": "claim", "statement": "Softmax 的输出可以直接当作模型置信度使用", "conditions": ["边界：未校准的概率分布会系统性偏高"], "evidence": "判断题表：Softmax 的输出可以直接当作模型置信度使用 —— 不成立", "breadth": {"outlinePath": "s5-1", "cardId": "crd.s5-1", "cardSummary": "ReLU 在整个实数域上处处可微；不成立；x=0 处左右导数不等", "leafContent": "ReLU 在整个实数域上处处可微；不成立；x=0 处左右导数不等"}, "depth": {"edges": [], "judgementPanel": {"question": "这个说法成立吗？", "expected": false, "reveal": {"explanation": "这个说法不成立。原文依据：判断题表：Softmax 的输出可以直接当作模型置信度使用 —— 不成立", "errorKinds": [{"kind": "semantic", "why": "表格判断题未标注错点类型，按语义依赖处理"}], "misconception": ""}}, "probeState": {"probe_status": "unprobed", "last_probed_at": null, "misconceptions": [], "confidence": 0.0, "attempts": 0, "correct": 0}}}');
INSERT OR REPLACE INTO kg_edge (id, from_id, to_id, type, condition_kind, premise, boundary, counterexample, weight, evidence) VALUES ('edg.pre.14d21a', 'clm.arch.ffn.linear-in-dim.4a3e', 'clm.arch.dep.shape.85dd', 'prerequisite', 'shape', '只有最后一维对齐才能做矩阵乘', '输入至少是二维；一维输入会被当成单样本处理', '把 (N, C) 的 C 与 in_features 混为一谈', 0.92, '输入 x 的形状通常是 (N, in_features)，权重 W 的形状是 (out_features, in_features)。');
INSERT OR REPLACE INTO kg_edge (id, from_id, to_id, type, condition_kind, premise, boundary, counterexample, weight, evidence) VALUES ('edg.aff.2366f8', 'clm.arch.ffn.relu-zero-grad.8ab0', 'clm.arch.dep.grad-relu-dead.ebf3', 'affects', 'gradient', '死区一旦形成，梯度通道被永久切断', '只在输入持续为负时成立', '换成 LeakyReLU 后负半轴仍有小梯度', 0.88, '输入为负时导数为 0，该神经元的参数在这一步不会更新。');
INSERT OR REPLACE INTO kg_edge (id, from_id, to_id, type, condition_kind, premise, boundary, counterexample, weight, evidence) VALUES ('edg.ctr.daab6c', 'clm.arch.ffn.relu-differentiable.a702', 'clm.arch.ffn.relu-zero-grad.8ab0', 'contrasts', 'gradient', '两者都谈 0 附近的行为，但一个是「不可微」，一个是「梯度为零」', '只在 x=0 这一点上区分', '无', 0.6, '输入为负时导数为 0；x=0 处左右导数分别为 0 与 1。');
INSERT OR REPLACE INTO kg_edge (id, from_id, to_id, type, condition_kind, premise, boundary, counterexample, weight, evidence) VALUES ('edg.dep.e6b1e6', 'clm.arch.ffn.softmax-sum.a505', 'clm.arch.ffn.softmax-dim.4af1', 'depends_on', 'statistics', '求和为 1 的前提是沿类别维归约', '类别维必须是最后一维或显式指定', '对 (N, C) 沿 N 求和得到的是每类的批内占比', 0.9, '每一行求和为 1。');
INSERT OR REPLACE INTO kg_edge (id, from_id, to_id, type, condition_kind, premise, boundary, counterexample, weight, evidence) VALUES ('edg.dep.ac6e04', 'clm.arch.ffn.ce-logits.5a91', 'clm.arch.ffn.softmax-shift.6358', 'depends_on', 'range', 'log-softmax 的稳定实现依赖平移不变性', '仅在实数 logits 上成立', '输入已是概率（0~1）时平移不再等价', 0.7, 'CrossEntropy 接收的是未归一化的 logits，内部已经做了 log-softmax。');
INSERT OR REPLACE INTO kg_edge (id, from_id, to_id, type, condition_kind, premise, boundary, counterexample, weight, evidence) VALUES ('edg.ref.c1339e', 'clm.arch.ffn.ce-double-softmax.eed8', 'clm.arch.ffn.ce-logits.5a91', 'refutes', 'gradient', '多一次 Softmax 就多一层雅可比，梯度被二次压缩', '当 logits 数值很大时差异更明显', 'logits 极小时两者数值几乎一致，容易误判为等价', 0.95, '先 Softmax 再送 CrossEntropy，数学上不等于直接送 logits。');
INSERT OR REPLACE INTO kg_edge (id, from_id, to_id, type, condition_kind, premise, boundary, counterexample, weight, evidence) VALUES ('edg.ctr.1c8d20', 'clm.arch.dep.bn-small-batch.b33d', 'clm.arch.dep.stats-dim.e92b', 'contrasts', 'statistics', '两者公式相同，差别只在归一化的维度', '在 batch>=32 时差异不明显', 'batch=1 时 BatchNorm 方差为 0', 0.8, 'BatchNorm 在 batch 维上算，batch 太小统计量就不可靠。');
INSERT OR REPLACE INTO kg_edge (id, from_id, to_id, type, condition_kind, premise, boundary, counterexample, weight, evidence) VALUES ('edg.ctr.47718c', 'clm.arch.dep.semantic.7874', 'clm.arch.dep.shape.85dd', 'contrasts', 'semantic', '形状依赖可机器检查，语义依赖只能靠人判断', '在逐元素激活之间接续时两者恰好一致', 'ReLU 之后接 Softmax，形状对但语义错', 0.85, '形状对得上、值域也合适，但含义不对。');
INSERT OR REPLACE INTO kg_edge (id, from_id, to_id, type, condition_kind, premise, boundary, counterexample, weight, evidence) VALUES ('edg.dep.b141d0', 'clm.arch.dep.relu-then-softmax.d07e', 'clm.arch.ffn.relu-shape.6092', 'depends_on', 'shape', '该判断以「ReLU 保持形状」为前提', '一旦换成会改变通道数的激活，形状前提就不成立', '换成会 reshape 的激活层', 0.9, '形状完全相容，可 ReLU 的输出不是 logits。');
INSERT OR REPLACE INTO kg_edge (id, from_id, to_id, type, condition_kind, premise, boundary, counterexample, weight, evidence) VALUES ('edg.ref.e76580', 'clm.arch.dep.relu-then-softmax.d07e', 'clm.arch.dep.semantic.7874', 'refutes', 'semantic', '它是「形状对就语义对」的反例', '仅在分类头场景成立', '无', 0.95, '形状完全相容，可 ReLU 的输出不是 logits。');
INSERT OR REPLACE INTO kg_edge (id, from_id, to_id, type, condition_kind, premise, boundary, counterexample, weight, evidence) VALUES ('edg.aff.8c0164', 'clm.arch.dep.relu-then-softmax.d07e', 'clm.arch.ffn.softmax-dim.4af1', 'affects', 'statistics', '归一化维度决定「概率」是不是按类别算的', '类别维必须是最后一维', '沿 batch 维归一化', 0.6, '形状完全相容，可 ReLU 的输出不是 logits。');
INSERT OR REPLACE INTO kg_edge (id, from_id, to_id, type, condition_kind, premise, boundary, counterexample, weight, evidence) VALUES ('edg.pre.8eef96', 'clm.arch.train.residual-shape.b560', 'clm.arch.dep.grad-residual.8054', 'prerequisite', 'shape', '形状一致是梯度能走捷径的前提', '仅在恒等捷径下成立', '通道数翻倍但未投影', 0.9, '主分支输出与捷径必须同形状。');
INSERT OR REPLACE INTO kg_edge (id, from_id, to_id, type, condition_kind, premise, boundary, counterexample, weight, evidence) VALUES ('edg.ctr.a7e9dd', 'clm.arch.train.post-ln-deep.d2c5', 'clm.arch.train.pre-ln.b81c', 'contrasts', 'gradient', '两者唯一差别是归一化相对残差的位置', '层数较少时差异可忽略', '40 层 Post-LN 不加 warmup 直接发散', 0.82, 'Post-LN 把归一化放在残差相加之后，深层网络训练更依赖 warmup。');
INSERT OR REPLACE INTO kg_edge (id, from_id, to_id, type, condition_kind, premise, boundary, counterexample, weight, evidence) VALUES ('edg.ref.747adc', 'clm.arch.attn.no-scale.1418', 'clm.arch.attn.scale.2883', 'refutes', 'statistics', '同一现象（更尖锐）的两种解释，只有一种对应可训练性', '仅在 d_k 较大时成立', 'd_k=8 时几乎看不出差别', 0.9, '不缩放会让 Softmax 进入饱和区，梯度接近 0。');
INSERT OR REPLACE INTO kg_edge (id, from_id, to_id, type, condition_kind, premise, boundary, counterexample, weight, evidence) VALUES ('edg.ctr.83bbb5', 'clm.arch.attn.mask-after.ca87', 'clm.arch.attn.mask-before-softmax.f3c1', 'contrasts', 'statistics', '两者输出在屏蔽位置都接近 0，差别在分母', '序列长度>1 时才有差别', '序列长度 1 时两者完全一致', 0.92, '先 Softmax 再乘 0 不等价。');
INSERT OR REPLACE INTO kg_edge (id, from_id, to_id, type, condition_kind, premise, boundary, counterexample, weight, evidence) VALUES ('edg.ref.89c977', 'clm.arch.attn.mha-heads-independent.b0da', 'clm.arch.attn.mha-concat.cffd', 'refutes', 'shape', '拼接维度回到 d_model，说明总量并未翻倍', '仅在 d_model 被均分时成立', '各头用独立全维投影时参数量确实翻倍', 0.75, '把 d_model 切成 h 份并行做注意力。');

-- 与现有业务表的衔接（生成式主题树，不重复存储）：
--   1) kg_node(kind='outline') 的 path 可作为 topic_table.tag_name 的前缀来源；
--   2) 一条用户收藏内容对某个命题的引用，建议落在 association_table（shared_topics 填命题 ID）；
--   3) 判断状态不要抄进 topic_table —— 广度侧必须从 kg_node.probe_status 派生。
